content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --success-color: #10b981;
  --success-bg: #d1fae5;
  --error-color: #ef4444;
  --error-bg: #fee2e2;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-sub: #4b5563;
  --border-color: #e5e7eb;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 16px;
}

.quiz-card {
  background-color: var(--card-bg);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 24px;
  width: 100%;
}

.question-text {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 24px;
  word-break: break-all;
}

.options-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.option-btn {
  width: 100%;
  padding: 14px 16px;
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
  background-color: #ffffff;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.2s ease;
  touch-action: manipulation;
}

.option-btn:hover:not(:disabled) {
  background-color: #f8fafc;
  border-color: var(--primary-color);
}

.option-btn:focus-visible {
  outline: 3px solid var(--primary-color);
  outline-offset: 2px;
}

.option-btn:disabled {
  cursor: default;
}

.option-btn.correct,
.correct {
  background-color: var(--success-bg) !important;
  border-color: var(--success-color) !important;
  color: #065f46 !important;
}

.option-btn.incorrect,
.incorrect {
  background-color: var(--error-bg) !important;
  border-color: var(--error-color) !important;
  color: #991b1b !important;
}

.explanation-box {
  background-color: #f8fafc;
  border-left: 4px solid var(--primary-color);
  padding: 16px;
  border-radius: 4px;
  margin-bottom: 24px;
  font-size: 0.95rem;
  color: var(--text-sub);
}

.next-btn,
.reset-btn {
  display: block;
  width: 100%;
  padding: 14px;
  font-size: 1rem;
  font-weight: 700;
  color: #ffffff;
  background-color: var(--primary-color);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  text-align: center;
  transition: background-color 0.2s ease;
  touch-action: manipulation;
}

.next-btn:hover,
.reset-btn:hover {
  background-color: var(--primary-hover);
}

.next-btn:focus-visible,
.reset-btn:focus-visible {
  outline: 3px solid var(--primary-hover);
  outline-offset: 2px;
}

.score-container {
  text-align: center;
}

.score-container h2 {
  font-size: 1.75rem;
  margin-bottom: 16px;
  color: var(--text-main);
}

.score-container p {
  font-size: 1.2rem;
  margin-bottom: 24px;
  color: var(--text-sub);
}

@media (max-width: 480px) {
  body {
    padding: 8px;
  }
  .app-container {
    padding: 8px;
  }
  .quiz-card {
    padding: 16px;
  }
  .question-text {
    font-size: 1.1rem;
    margin-bottom: 16px;
  }
  .option-btn {
    padding: 12px;
    font-size: 0.95rem;
  }
  .score-container h2 {
    font-size: 1.5rem;
  }
  .score-container p {
    font-size: 1.05rem;
  }
}

export interface Question {
  id: string | number;
  question: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  category?: string;
  difficulty?: string;
}

export interface QuizState {
  currentQuestionIndex: number;
  selectedOption: number | null;
  score: number;
  isAnswered: boolean;
  isFinished: boolean;
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { QuizState } from './types';
import { questions } from './data/questions';

const STORAGE_KEY = 'japan_geo_quiz_state';

export default function App() {
  const [quizState, setQuizState] = useState<QuizState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (
          typeof parsed === 'object' &&
          parsed !== null &&
          typeof parsed.currentQuestionIndex === 'number' &&
          parsed.currentQuestionIndex >= 0 &&
          parsed.currentQuestionIndex < questions.length &&
          typeof parsed.score === 'number' &&
          typeof parsed.isAnswered === 'boolean' &&
          typeof parsed.isFinished === 'boolean'
        ) {
          return parsed;
        }
      } catch (e) {
        console.error('Failed to parse quiz state from localStorage:', e);
      }
    }
    return {
      currentQuestionIndex: 0,
      selectedOption: null,
      score: 0,
      isAnswered: false,
      isFinished: false,
    };
  });

  const nextButtonRef = useRef<HTMLButtonElement>(null);
  const resetButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quizState));
  }, [quizState]);

  useEffect(() => {
    if (quizState.isAnswered && !quizState.isFinished) {
      nextButtonRef.current?.focus();
    } else if (quizState.isFinished) {
      resetButtonRef.current?.focus();
    }
  }, [quizState.isAnswered, quizState.isFinished]);

  const safeIndex = Math.min(Math.max(0, quizState.currentQuestionIndex), questions.length - 1);
  const currentQuestion = questions[safeIndex];

  const handleSelectOption = useCallback((index: number) => {
    if (quizState.isAnswered || quizState.isFinished || !currentQuestion) return;

    const isCorrect = index === currentQuestion.correctAnswer;
    setQuizState((prev) => ({
      ...prev,
      selectedOption: index,
      score: isCorrect ? prev.score + 1 : prev.score,
      isAnswered: true,
    }));
  }, [quizState.isAnswered, quizState.isFinished, currentQuestion]);

  const handleNextQuestion = useCallback(() => {
    if (!quizState.isAnswered || quizState.isFinished) return;

    const nextIndex = quizState.currentQuestionIndex + 1;
    if (nextIndex < questions.length) {
      setQuizState((prev) => ({
        ...prev,
        currentQuestionIndex: nextIndex,
        selectedOption: null,
        isAnswered: false,
      }));
    } else {
      setQuizState((prev) => ({
        ...prev,
        isFinished: true,
      }));
    }
  }, [quizState.isAnswered, quizState.isFinished, quizState.currentQuestionIndex]);

  const handleReset = useCallback(() => {
    const initialState: QuizState = {
      currentQuestionIndex: 0,
      selectedOption: null,
      score: 0,
      isAnswered: false,
      isFinished: false,
    };
    setQuizState(initialState);
    localStorage.removeItem(STORAGE_KEY);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (quizState.isFinished) {
        if (e.key === 'Enter') {
          handleReset();
        }
        return;
      }

      if (!quizState.isAnswered && currentQuestion) {
        if (e.key >= '1' && e.key <= '4') {
          const index = parseInt(e.key, 10) - 1;
          if (index < currentQuestion.options.length) {
            handleSelectOption(index);
          }
        }
      } else {
        if (e.key === 'Enter') {
          handleNextQuestion();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [quizState.isAnswered, quizState.isFinished, currentQuestion, handleSelectOption, handleNextQuestion, handleReset]);

  if (!currentQuestion) {
    return null;
  }

  return (
    <div className="app-container">
      <div className="quiz-card">
        {!quizState.isFinished ? (
          <div>
            <div style={{ marginBottom: '16px', color: 'var(--text-sub)', fontSize: '0.9rem', fontWeight: 600 }}>
              第 {safeIndex + 1} 問 / 全 {questions.length} 問
            </div>
            <h2 className="question-text">{currentQuestion.question}</h2>
            <div className="options-container">
              {currentQuestion.options.map((option, index) => {
                let btnClass = 'option-btn';
                if (quizState.isAnswered) {
                  if (index === currentQuestion.correctAnswer) {
                    btnClass += ' correct';
                  } else if (index === quizState.selectedOption) {
                    btnClass += ' incorrect';
                  }
                }
                return (
                  <button
                    key={index}
                    className={btnClass}
                    onClick={() => handleSelectOption(index)}
                    disabled={quizState.isAnswered}
                  >
                    {index + 1}. {option}
                  </button>
                );
              })}
            </div>

            {quizState.isAnswered && (
              <div>
                <div className="explanation-box">
                  <strong>【解説】</strong>
                  <p style={{ marginTop: '4px' }}>{currentQuestion.explanation}</p>
                </div>
                <button ref={nextButtonRef} className="next-btn" onClick={handleNextQuestion}>
                  {safeIndex < questions.length - 1 ? '次の問題へ (Enter)' : '結果を見る (Enter)'}
                </button>
              </div>
            )}
          </div>
        ) : (
          <div className="score-container">
            <h2>クイズ終了！</h2>
            <p>
              正解数：{quizState.score} / {questions.length} 問
            </p>
            <button ref={resetButtonRef} className="reset-btn" onClick={handleReset}>
              もう一度やり直す (Enter)
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

